CREATE TABLE IF NOT EXISTS "exclusion_groups" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stable identifier used in code, e.g. checkout_surface.
	"key" VARCHAR(60) NOT NULL UNIQUE,
	-- Display name for the group of experiments that must not overlap.
	"name" VARCHAR(160) NOT NULL,
	-- Size of the shared bucket space the members carve up. Ten thousand gives allocation to one hundredth of a percent.
	"total_slots" INTEGER NOT NULL DEFAULT 10000,
	-- Salt for the group bucket function. Members hash with this seed instead of their own, which is what puts them on one shared number line.
	"hash_seed" VARCHAR(64) NOT NULL,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "exclusion_groups" IS 'Mutual exclusion. Two experiments that change the same surface would confound each other, so they join a group, are hashed with the same seed, and are given disjoint slot ranges — a subject can then land in at most one of them.';
COMMENT ON COLUMN "exclusion_groups"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "exclusion_groups"."key" IS 'Stable identifier used in code, e.g. checkout_surface.';
COMMENT ON COLUMN "exclusion_groups"."name" IS 'Display name for the group of experiments that must not overlap.';
COMMENT ON COLUMN "exclusion_groups"."total_slots" IS 'Size of the shared bucket space the members carve up. Ten thousand gives allocation to one hundredth of a percent.';
COMMENT ON COLUMN "exclusion_groups"."hash_seed" IS 'Salt for the group bucket function. Members hash with this seed instead of their own, which is what puts them on one shared number line.';
COMMENT ON COLUMN "exclusion_groups"."created_at" IS 'Creation time.';

CREATE TABLE IF NOT EXISTS "experiments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Identifier the SDK asks for. Stable forever, because it is compiled into client code you cannot recall.
	"key" VARCHAR(80) NOT NULL UNIQUE,
	-- Human name shown in the dashboard.
	"name" VARCHAR(200) NOT NULL,
	-- What you expect to happen and why. Stored because a result without the prior question is unreadable six months later.
	"hypothesis" TEXT,
	-- user | account | session | device. The randomisation unit, and the one decision you cannot change mid-flight.
	"subject_type" VARCHAR(24) NOT NULL DEFAULT 'user',
	-- draft | running | paused | stopped | completed. Only running experiments assign new subjects.
	"status" VARCHAR(20) NOT NULL DEFAULT 'draft',
	-- Salt mixed with the subject key before hashing. Changing it reshuffles everyone, which is why it is a stored value and not the experiment key.
	"hash_seed" VARCHAR(64) NOT NULL,
	-- Share of eligible subjects admitted at all. Ramping this up is how an experiment is exposed gradually without touching variant weights.
	"traffic_percent" SMALLINT NOT NULL DEFAULT 100,
	-- Group whose slot space this experiment draws from. Null means it overlaps freely with everything else.
	"exclusion_group_id" BIGINT,
	-- First slot in the group reserved for this experiment. Null when unconstrained.
	"bucket_low" INTEGER,
	-- Last reserved slot, exclusive. Disjoint ranges are what enforce mutual exclusion.
	"bucket_high" INTEGER,
	-- The metric the decision is made on. Everything else is secondary or a guardrail.
	"primary_metric_id" BIGINT,
	-- Set when a decision is made. Null while the experiment is still a question.
	"winner_variant_id" BIGINT,
	-- First moment assignments were served; the lower bound of every analysis window.
	"started_at" TIMESTAMP,
	-- When assignment stopped. Events after this are still collected but excluded from the primary analysis.
	"ended_at" TIMESTAMP,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "experiments" IS 'The unit of decision. The randomisation unit and the hash seed are stored rather than derived, because an experiment whose bucketing function changes halfway through is not one experiment any more.';
COMMENT ON COLUMN "experiments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "experiments"."key" IS 'Identifier the SDK asks for. Stable forever, because it is compiled into client code you cannot recall.';
COMMENT ON COLUMN "experiments"."name" IS 'Human name shown in the dashboard.';
COMMENT ON COLUMN "experiments"."hypothesis" IS 'What you expect to happen and why. Stored because a result without the prior question is unreadable six months later.';
COMMENT ON COLUMN "experiments"."subject_type" IS 'user | account | session | device. The randomisation unit, and the one decision you cannot change mid-flight.';
COMMENT ON COLUMN "experiments"."status" IS 'draft | running | paused | stopped | completed. Only running experiments assign new subjects.';
COMMENT ON COLUMN "experiments"."hash_seed" IS 'Salt mixed with the subject key before hashing. Changing it reshuffles everyone, which is why it is a stored value and not the experiment key.';
COMMENT ON COLUMN "experiments"."traffic_percent" IS 'Share of eligible subjects admitted at all. Ramping this up is how an experiment is exposed gradually without touching variant weights.';
COMMENT ON COLUMN "experiments"."exclusion_group_id" IS 'Group whose slot space this experiment draws from. Null means it overlaps freely with everything else.';
COMMENT ON COLUMN "experiments"."bucket_low" IS 'First slot in the group reserved for this experiment. Null when unconstrained.';
COMMENT ON COLUMN "experiments"."bucket_high" IS 'Last reserved slot, exclusive. Disjoint ranges are what enforce mutual exclusion.';
COMMENT ON COLUMN "experiments"."primary_metric_id" IS 'The metric the decision is made on. Everything else is secondary or a guardrail.';
COMMENT ON COLUMN "experiments"."winner_variant_id" IS 'Set when a decision is made. Null while the experiment is still a question.';
COMMENT ON COLUMN "experiments"."started_at" IS 'First moment assignments were served; the lower bound of every analysis window.';
COMMENT ON COLUMN "experiments"."ended_at" IS 'When assignment stopped. Events after this are still collected but excluded from the primary analysis.';
COMMENT ON COLUMN "experiments"."created_at" IS 'Creation time.';

CREATE INDEX "idx_experiments_status_started"
ON "experiments" ("status", "started_at");

CREATE TABLE IF NOT EXISTS "variants" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent experiment.
	"experiment_id" BIGINT NOT NULL,
	-- Identifier returned to the SDK, e.g. control or treatment_b.
	"key" VARCHAR(60) NOT NULL,
	-- Display name in reports.
	"name" VARCHAR(160) NOT NULL,
	-- Exactly one variant per experiment is the baseline every lift is measured against.
	"is_control" BOOLEAN NOT NULL DEFAULT false,
	-- Relative share of admitted traffic. Weights map to contiguous slot ranges, so a 50/50 split is slots 0-4999 and 5000-9999.
	"traffic_weight" SMALLINT NOT NULL DEFAULT 50,
	-- Payload handed to the client: copy, colours, feature parameters. JSON because the shape differs per experiment.
	"config" JSONB,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "variants" IS 'A treatment arm. Weights are stored as integers rather than percentages so the slot boundaries are exact; floating-point splits are how a 33/33/34 test quietly loses subjects at the seam.';
COMMENT ON COLUMN "variants"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "variants"."experiment_id" IS 'Parent experiment.';
COMMENT ON COLUMN "variants"."key" IS 'Identifier returned to the SDK, e.g. control or treatment_b.';
COMMENT ON COLUMN "variants"."name" IS 'Display name in reports.';
COMMENT ON COLUMN "variants"."is_control" IS 'Exactly one variant per experiment is the baseline every lift is measured against.';
COMMENT ON COLUMN "variants"."traffic_weight" IS 'Relative share of admitted traffic. Weights map to contiguous slot ranges, so a 50/50 split is slots 0-4999 and 5000-9999.';
COMMENT ON COLUMN "variants"."config" IS 'Payload handed to the client: copy, colours, feature parameters. JSON because the shape differs per experiment.';

CREATE UNIQUE INDEX "uq_variants_experiment_key"
ON "variants" ("experiment_id", "key");

CREATE TABLE IF NOT EXISTS "assignments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Experiment the subject was bucketed into.
	"experiment_id" BIGINT NOT NULL,
	-- Variant the hash resolved to.
	"variant_id" BIGINT NOT NULL,
	-- Identifier of the randomisation unit — a user id, account id or anonymous device id. Text, because the unit type varies per experiment.
	"subject_key" VARCHAR(120) NOT NULL,
	-- The hash output, 0 to total_slots-1. Stored so a support question about one user is answered by reading a row, not by re-running a hash in your head.
	"bucket" INTEGER NOT NULL,
	-- First time this subject was resolved.
	"assigned_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "assignments" IS 'A record of bucketing, not the source of truth for it. The variant is computed as hash(hash_seed + subject_key) modulo total_slots and compared against the weight ranges, so the SDK can answer offline and identically on every machine; this table exists for auditing, for joins during analysis, and to keep an assignment stable if weights are later edited.';
COMMENT ON COLUMN "assignments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "assignments"."experiment_id" IS 'Experiment the subject was bucketed into.';
COMMENT ON COLUMN "assignments"."variant_id" IS 'Variant the hash resolved to.';
COMMENT ON COLUMN "assignments"."subject_key" IS 'Identifier of the randomisation unit — a user id, account id or anonymous device id. Text, because the unit type varies per experiment.';
COMMENT ON COLUMN "assignments"."bucket" IS 'The hash output, 0 to total_slots-1. Stored so a support question about one user is answered by reading a row, not by re-running a hash in your head.';
COMMENT ON COLUMN "assignments"."assigned_at" IS 'First time this subject was resolved.';

CREATE UNIQUE INDEX "uq_assignments_experiment_subject"
ON "assignments" ("experiment_id", "subject_key");
CREATE INDEX "idx_assignments_experiment_variant"
ON "assignments" ("experiment_id", "variant_id");

CREATE TABLE IF NOT EXISTS "exposures" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Experiment the subject was exposed to.
	"experiment_id" BIGINT NOT NULL,
	-- Variant actually shown.
	"variant_id" BIGINT NOT NULL,
	-- Randomisation unit that saw it.
	"subject_key" VARCHAR(120) NOT NULL,
	-- Client event time. The start of this subject observation window.
	"occurred_at" TIMESTAMP NOT NULL,
	-- Platform, app version, country, entry page. What every segmented read of the results slices on.
	"context" JSONB,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "exposures" IS 'Proof that a subject actually saw the treatment, logged at the point of render rather than at assignment. Analysing on assignment instead inflates the denominator with people who never reached the surface, which dilutes a real effect toward zero.';
COMMENT ON COLUMN "exposures"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "exposures"."experiment_id" IS 'Experiment the subject was exposed to.';
COMMENT ON COLUMN "exposures"."variant_id" IS 'Variant actually shown.';
COMMENT ON COLUMN "exposures"."subject_key" IS 'Randomisation unit that saw it.';
COMMENT ON COLUMN "exposures"."occurred_at" IS 'Client event time. The start of this subject observation window.';
COMMENT ON COLUMN "exposures"."context" IS 'Platform, app version, country, entry page. What every segmented read of the results slices on.';

CREATE INDEX "idx_exposures_experiment_time"
ON "exposures" ("experiment_id", "occurred_at");
CREATE INDEX "idx_exposures_subject"
ON "exposures" ("experiment_id", "subject_key", "occurred_at");

CREATE TABLE IF NOT EXISTS "metric_definitions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Identifier used when emitting observations, e.g. checkout_completed.
	"key" VARCHAR(80) NOT NULL UNIQUE,
	-- Display name.
	"name" VARCHAR(160) NOT NULL,
	-- conversion | count | revenue | duration | ratio. Determines which statistical test is valid; a conversion rate and an average order value are not analysed the same way.
	"metric_type" VARCHAR(20) NOT NULL,
	-- sum | average | unique_count. How per-subject observations collapse into one number per subject.
	"aggregation" VARCHAR(20) NOT NULL DEFAULT 'sum',
	-- increase | decrease. Which way is good, so a lift can be labelled a win without a human reading the metric name.
	"direction" VARCHAR(12) NOT NULL DEFAULT 'increase',
	-- Guardrails are watched for harm rather than improvement — latency, error rate, refund rate.
	"is_guardrail" BOOLEAN NOT NULL DEFAULT false,
	-- Attribution window after exposure. Null means the whole experiment period.
	"window_hours" INTEGER,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "metric_definitions" IS 'The catalogue of measurable outcomes, defined once and reused across experiments. Defining metrics per experiment is how two teams end up with two conversion rates that disagree.';
COMMENT ON COLUMN "metric_definitions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "metric_definitions"."key" IS 'Identifier used when emitting observations, e.g. checkout_completed.';
COMMENT ON COLUMN "metric_definitions"."name" IS 'Display name.';
COMMENT ON COLUMN "metric_definitions"."metric_type" IS 'conversion | count | revenue | duration | ratio. Determines which statistical test is valid; a conversion rate and an average order value are not analysed the same way.';
COMMENT ON COLUMN "metric_definitions"."aggregation" IS 'sum | average | unique_count. How per-subject observations collapse into one number per subject.';
COMMENT ON COLUMN "metric_definitions"."direction" IS 'increase | decrease. Which way is good, so a lift can be labelled a win without a human reading the metric name.';
COMMENT ON COLUMN "metric_definitions"."is_guardrail" IS 'Guardrails are watched for harm rather than improvement — latency, error rate, refund rate.';
COMMENT ON COLUMN "metric_definitions"."window_hours" IS 'Attribution window after exposure. Null means the whole experiment period.';

CREATE TABLE IF NOT EXISTS "experiment_metrics" (
	-- Experiment. Part of the composite key.
	"experiment_id" BIGINT,
	-- Metric being tracked. Part of the composite key.
	"metric_id" BIGINT,
	-- primary | secondary | guardrail. Only the primary metric can end the experiment; secondaries exist to explain the result.
	"role" VARCHAR(16) NOT NULL DEFAULT 'secondary',
	-- Relative effect the experiment was powered to detect. Recorded up front, because deciding it after seeing the data is how a null result becomes a win.
	"minimum_detectable_effect" DECIMAL(8,4),
	PRIMARY KEY("experiment_id", "metric_id")
);

COMMENT ON TABLE "experiment_metrics" IS 'Which metrics an experiment is judged on, and in what role. Declaring it before launch is the whole defence against cherry-picking the one of forty metrics that happened to move.';
COMMENT ON COLUMN "experiment_metrics"."experiment_id" IS 'Experiment. Part of the composite key.';
COMMENT ON COLUMN "experiment_metrics"."metric_id" IS 'Metric being tracked. Part of the composite key.';
COMMENT ON COLUMN "experiment_metrics"."role" IS 'primary | secondary | guardrail. Only the primary metric can end the experiment; secondaries exist to explain the result.';
COMMENT ON COLUMN "experiment_metrics"."minimum_detectable_effect" IS 'Relative effect the experiment was powered to detect. Recorded up front, because deciding it after seeing the data is how a null result becomes a win.';

CREATE TABLE IF NOT EXISTS "metric_events" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Metric observed.
	"metric_id" BIGINT NOT NULL,
	-- Randomisation unit the observation belongs to. Joined to exposures at analysis time rather than carrying a variant, so a late-arriving event is attributed correctly.
	"subject_key" VARCHAR(120) NOT NULL,
	-- Observed value. Conversions emit 1; revenue metrics store minor units here so money never touches a float.
	"value_numeric" DECIMAL(18,6) NOT NULL DEFAULT 1,
	-- Event time, compared against the exposure to apply the attribution window.
	"occurred_at" TIMESTAMP NOT NULL,
	-- Client-supplied idempotency key. A retried event pipeline is the most common cause of an impossible 300% lift.
	"dedupe_key" VARCHAR(120) UNIQUE,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "metric_events" IS 'Raw per-subject observations, deliberately not tagged with an experiment. One event stream feeds every experiment running at the time, which is what lets you add a metric to an analysis after the fact instead of relaunching.';
COMMENT ON COLUMN "metric_events"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "metric_events"."metric_id" IS 'Metric observed.';
COMMENT ON COLUMN "metric_events"."subject_key" IS 'Randomisation unit the observation belongs to. Joined to exposures at analysis time rather than carrying a variant, so a late-arriving event is attributed correctly.';
COMMENT ON COLUMN "metric_events"."value_numeric" IS 'Observed value. Conversions emit 1; revenue metrics store minor units here so money never touches a float.';
COMMENT ON COLUMN "metric_events"."occurred_at" IS 'Event time, compared against the exposure to apply the attribution window.';
COMMENT ON COLUMN "metric_events"."dedupe_key" IS 'Client-supplied idempotency key. A retried event pipeline is the most common cause of an impossible 300% lift.';

CREATE INDEX "idx_metric_events_subject"
ON "metric_events" ("metric_id", "subject_key", "occurred_at");

CREATE TABLE IF NOT EXISTS "variant_daily_stats" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Experiment being summarised.
	"experiment_id" BIGINT NOT NULL,
	-- Arm being summarised.
	"variant_id" BIGINT NOT NULL,
	-- Metric being summarised.
	"metric_id" BIGINT NOT NULL,
	-- Local day of the aggregation. Daily grain keeps a time series available for peeking curves.
	"stat_date" DATE NOT NULL,
	-- Exposed subjects in the day, the denominator of every rate.
	"subject_count" BIGINT NOT NULL DEFAULT 0,
	-- Subjects with at least one observation. Used for conversion-type metrics.
	"converted_count" BIGINT NOT NULL DEFAULT 0,
	-- Sum of per-subject values, the numerator of the mean.
	"value_sum" DECIMAL(24,6) NOT NULL DEFAULT 0,
	-- Sum of squared per-subject values. Storing it is what makes variance computable incrementally, without ever rescanning the raw events.
	"value_sum_squares" DECIMAL(30,6) NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "variant_daily_stats" IS 'Pre-aggregated sufficient statistics, one row per variant, metric and day. Count, sum and sum of squares are all a t-test needs, so results recompute in milliseconds and the raw event tables can be aged out without losing the ability to re-analyse.';
COMMENT ON COLUMN "variant_daily_stats"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "variant_daily_stats"."experiment_id" IS 'Experiment being summarised.';
COMMENT ON COLUMN "variant_daily_stats"."variant_id" IS 'Arm being summarised.';
COMMENT ON COLUMN "variant_daily_stats"."metric_id" IS 'Metric being summarised.';
COMMENT ON COLUMN "variant_daily_stats"."stat_date" IS 'Local day of the aggregation. Daily grain keeps a time series available for peeking curves.';
COMMENT ON COLUMN "variant_daily_stats"."subject_count" IS 'Exposed subjects in the day, the denominator of every rate.';
COMMENT ON COLUMN "variant_daily_stats"."converted_count" IS 'Subjects with at least one observation. Used for conversion-type metrics.';
COMMENT ON COLUMN "variant_daily_stats"."value_sum" IS 'Sum of per-subject values, the numerator of the mean.';
COMMENT ON COLUMN "variant_daily_stats"."value_sum_squares" IS 'Sum of squared per-subject values. Storing it is what makes variance computable incrementally, without ever rescanning the raw events.';

CREATE UNIQUE INDEX "uq_variant_stats_grain"
ON "variant_daily_stats" ("experiment_id", "variant_id", "metric_id", "stat_date");

CREATE TABLE IF NOT EXISTS "experiment_results" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Experiment analysed.
	"experiment_id" BIGINT NOT NULL,
	-- Arm compared against the control.
	"variant_id" BIGINT NOT NULL,
	-- Metric analysed.
	"metric_id" BIGINT NOT NULL,
	-- When this analysis ran. Results are inserted, never updated, so the history of a peeking decision survives.
	"computed_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- frequentist | bayesian | sequential. Sequential tests are what make daily peeking statistically honest.
	"method" VARCHAR(20) NOT NULL DEFAULT 'frequentist',
	-- Exposed subjects in the window.
	"subject_count" BIGINT NOT NULL,
	-- Per-subject mean for this arm.
	"mean_value" DECIMAL(18,6),
	-- Change against control as a ratio. Null for the control row itself.
	"relative_lift" DECIMAL(10,6),
	-- Lower bound of the interval on the lift. An interval spanning zero is the answer "we do not know yet".
	"confidence_lower" DECIMAL(10,6),
	-- Upper bound of the same interval.
	"confidence_upper" DECIMAL(10,6),
	-- Probability of an effect this large under the null. Null for Bayesian runs, which report a probability of beating control instead.
	"p_value" DECIMAL(10,8),
	-- Whether the configured threshold was met. Stored so the dashboard and the decision log cannot disagree.
	"is_significant" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "experiment_results" IS 'One row per arm, metric and analysis run. Append-only on purpose: an experiment that looked significant on Tuesday and did not on Friday is an important fact about the experiment, and overwriting the row hides it.';
COMMENT ON COLUMN "experiment_results"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "experiment_results"."experiment_id" IS 'Experiment analysed.';
COMMENT ON COLUMN "experiment_results"."variant_id" IS 'Arm compared against the control.';
COMMENT ON COLUMN "experiment_results"."metric_id" IS 'Metric analysed.';
COMMENT ON COLUMN "experiment_results"."computed_at" IS 'When this analysis ran. Results are inserted, never updated, so the history of a peeking decision survives.';
COMMENT ON COLUMN "experiment_results"."method" IS 'frequentist | bayesian | sequential. Sequential tests are what make daily peeking statistically honest.';
COMMENT ON COLUMN "experiment_results"."subject_count" IS 'Exposed subjects in the window.';
COMMENT ON COLUMN "experiment_results"."mean_value" IS 'Per-subject mean for this arm.';
COMMENT ON COLUMN "experiment_results"."relative_lift" IS 'Change against control as a ratio. Null for the control row itself.';
COMMENT ON COLUMN "experiment_results"."confidence_lower" IS 'Lower bound of the interval on the lift. An interval spanning zero is the answer "we do not know yet".';
COMMENT ON COLUMN "experiment_results"."confidence_upper" IS 'Upper bound of the same interval.';
COMMENT ON COLUMN "experiment_results"."p_value" IS 'Probability of an effect this large under the null. Null for Bayesian runs, which report a probability of beating control instead.';
COMMENT ON COLUMN "experiment_results"."is_significant" IS 'Whether the configured threshold was met. Stored so the dashboard and the decision log cannot disagree.';

CREATE INDEX "idx_results_experiment_metric"
ON "experiment_results" ("experiment_id", "metric_id", "computed_at");

CREATE TABLE IF NOT EXISTS "rollouts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Experiment whose winner is being shipped.
	"experiment_id" BIGINT NOT NULL,
	-- Winning arm now being served as the default.
	"variant_id" BIGINT NOT NULL,
	-- Share of all traffic on the winner. Ramped 1, 10, 50, 100 rather than flipped, because a winner in a test can still break in production.
	"percent" SMALLINT NOT NULL DEFAULT 0,
	-- pending | ramping | completed | rolled_back. A rollback is a state, not a deletion.
	"status" VARCHAR(20) NOT NULL DEFAULT 'pending',
	-- When the ramp began.
	"started_at" TIMESTAMP,
	-- When the winner reached full traffic and the experiment stopped assigning.
	"completed_at" TIMESTAMP,
	-- Set if the ramp was reversed, with the reason below.
	"rolled_back_at" TIMESTAMP,
	-- Why the ramp was paused or reversed. The most-read field in the table during an incident.
	"notes" TEXT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "rollouts" IS 'The life of an experiment after the decision. Keeping the ramp here rather than deleting the experiment means the causal chain — hypothesis, result, ship, and any rollback — stays readable as one story.';
COMMENT ON COLUMN "rollouts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "rollouts"."experiment_id" IS 'Experiment whose winner is being shipped.';
COMMENT ON COLUMN "rollouts"."variant_id" IS 'Winning arm now being served as the default.';
COMMENT ON COLUMN "rollouts"."percent" IS 'Share of all traffic on the winner. Ramped 1, 10, 50, 100 rather than flipped, because a winner in a test can still break in production.';
COMMENT ON COLUMN "rollouts"."status" IS 'pending | ramping | completed | rolled_back. A rollback is a state, not a deletion.';
COMMENT ON COLUMN "rollouts"."started_at" IS 'When the ramp began.';
COMMENT ON COLUMN "rollouts"."completed_at" IS 'When the winner reached full traffic and the experiment stopped assigning.';
COMMENT ON COLUMN "rollouts"."rolled_back_at" IS 'Set if the ramp was reversed, with the reason below.';
COMMENT ON COLUMN "rollouts"."notes" IS 'Why the ramp was paused or reversed. The most-read field in the table during an incident.';

CREATE INDEX "idx_rollouts_experiment_status"
ON "rollouts" ("experiment_id", "status");

